contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (10) + (10));
        require(amount >= 20);
        require(address(this).balance >= amount);

        c.play{value: 10}(); if (__ESBMC_reverted()) return;
        uint pot1 = c.pot(); if (__ESBMC_reverted()) return;
        uint bal1 = address(c).balance;

        c.play{value: 10}(); if (__ESBMC_reverted()) return;
        uint pot2 = c.pot(); if (__ESBMC_reverted()) return;
        uint bal2 = address(c).balance;

        assert(
            (pot2 == pot1 + 10 && bal2 == bal1 + 10) ||
            (pot2 == 0 && bal2 + pot1 == bal1)
        );
    }

    receive() external payable {}
}

